(()=>{"use strict";
if(window.__JH_COGNIPAL_INIT__)return;
window.__JH_COGNIPAL_INIT__=true;
try{const path=(location.pathname||"").toLowerCase();if(path.endsWith("404.html")||document.body?.classList?.contains("jh-page-404"))return;}catch{}

const ICON_URL="https://assets.jonathan-harris.online/CogniPal.jpg";
const REVEAL_DELAY_MS=30000;
const EARLY_REVEAL_SCROLL_RATIO=.35;
const K={session:"jh:cognipal:session",visitor:"jh:cognipal:visitor",last:"jh:cognipal:last",engaged:"jh:cognipal:engaged"};
const id=(key,prefix)=>{let value="";try{value=localStorage.getItem(key)||""}catch{}if(!/^[A-Za-z0-9_.:-]{8,200}$/.test(value)){value=`${prefix}-${crypto.randomUUID()}`;try{localStorage.setItem(key,value)}catch{}}return value};
const sessionId=id(K.session,"ses"),visitorId=id(K.visitor,"vis");
let lastSync="",open=false,syncTimer=0,sending=false,humanMode="automation",launcherVisible=false,revealTimer=0;
try{lastSync=localStorage.getItem(K.last)||""}catch{}
const wasEngaged=(()=>{try{return localStorage.getItem(K.engaged)==="1"}catch{return false}})();

const root=document.createElement("div");
root.className="jh-cognipal";
root.innerHTML=`<button class="jh-cognipal__launcher" type="button" aria-label="Open CogniPal web chat" aria-expanded="false" hidden><img src="${ICON_URL}" alt="" aria-hidden="true" referrerpolicy="no-referrer"></button><section class="jh-cognipal__panel" role="dialog" aria-label="CogniPal website chat" hidden><header class="jh-cognipal__head"><div class="jh-cognipal__avatar" aria-hidden="true"><img src="${ICON_URL}" alt="" referrerpolicy="no-referrer"></div><div class="jh-cognipal__title"><strong>CogniPal</strong></div><button class="jh-cognipal__close" type="button" aria-label="Close web chat">×</button></header><div class="jh-cognipal__messages" aria-live="polite" aria-relevant="additions"></div><div class="jh-cognipal__status" role="status"></div><button class="jh-cognipal__human" type="button">Talk to Jonathan</button><form class="jh-cognipal__compose"><textarea class="jh-cognipal__input" maxlength="4000" rows="1" aria-label="Message" placeholder="Type a message…"></textarea><button class="jh-cognipal__send" type="submit" aria-label="Send message">➤</button></form><div class="jh-cognipal__foot">Messages go directly to Jonathan. <a href="/privacy-policy/">Privacy</a></div></section>`;
document.body.appendChild(root);
const launcher=root.querySelector(".jh-cognipal__launcher"),panel=root.querySelector(".jh-cognipal__panel"),close=root.querySelector(".jh-cognipal__close"),messages=root.querySelector(".jh-cognipal__messages"),status=root.querySelector(".jh-cognipal__status"),human=root.querySelector(".jh-cognipal__human"),form=root.querySelector(".jh-cognipal__compose"),input=root.querySelector(".jh-cognipal__input"),send=root.querySelector(".jh-cognipal__send");
const seen=new Set();

function revealLauncher(){if(launcherVisible)return;launcherVisible=true;clearTimeout(revealTimer);launcher.hidden=false;root.classList.add("jh-cognipal--ready");window.removeEventListener("scroll",maybeRevealOnScroll)}
function maybeRevealOnScroll(){const doc=document.documentElement;const scrollable=Math.max(1,(doc.scrollHeight||0)-window.innerHeight);if((window.scrollY||window.pageYOffset||0)/scrollable>=EARLY_REVEAL_SCROLL_RATIO)revealLauncher()}
if(wasEngaged){revealLauncher()}else{revealTimer=window.setTimeout(revealLauncher,REVEAL_DELAY_MS);window.addEventListener("scroll",maybeRevealOnScroll,{passive:true});maybeRevealOnScroll()}

function markEngaged(){try{localStorage.setItem(K.engaged,"1")}catch{}}
function addMessage(direction,body,when,label,idValue){if(idValue&&seen.has(idValue))return;if(idValue)seen.add(idValue);const row=document.createElement("div");row.className=`jh-cognipal__message jh-cognipal__message--${direction==="inbound"?"in":"out"}`;const bubble=document.createElement("div");bubble.className="jh-cognipal__bubble";const txt=document.createElement("div");txt.textContent=body;bubble.appendChild(txt);if(label||when){const meta=document.createElement("div");meta.className="jh-cognipal__meta";const date=when?new Date(when):null;meta.textContent=[label,date&&Number.isFinite(date.getTime())?date.toLocaleTimeString([],{hour:"2-digit",minute:"2-digit"}):""].filter(Boolean).join(" · ");bubble.appendChild(meta)}row.appendChild(bubble);messages.appendChild(row);messages.scrollTop=messages.scrollHeight}
addMessage("outbound","Hi, I’m CogniPal. Got a question? Ask away, or leave Jonathan a message.","","CogniPal","welcome");
function setStatus(value){status.textContent=value||""}
function busy(value){sending=value;send.disabled=value;human.disabled=value;input.disabled=value}
async function post(endpoint,payload){const response=await fetch(endpoint,{method:"POST",headers:{"content-type":"application/json","accept":"application/json"},body:JSON.stringify(payload),credentials:"same-origin"});const data=await response.json().catch(()=>({}));if(!response.ok||data.ok===false){const upstreamMessage=String(data.message||"");const friendly=response.status===404||/route\s+not\s+found/i.test(upstreamMessage)?"Web chat is reconnecting. Please try again in a moment.":(upstreamMessage||"Web chat is temporarily unavailable.");const error=new Error(friendly);error.status=response.status;throw error}return data}
function basePayload(){return{sessionId,visitorId,pageUrl:location.href,pageTitle:document.title||"",referrer:document.referrer||""}}
async function sync(){if(document.hidden||!open)return;try{const data=await post("/api/cognipal/sync",{...basePayload(),after:lastSync||undefined});humanMode=data.mode||"automation";(data.messages||[]).forEach(message=>{const received=message.receivedAt||message.createdAt||"";const label=message.direction==="inbound"?"You":(humanMode==="human"?"Jonathan":"CogniPal");addMessage(message.direction,message.bodyText||"",received,label,message.id);if(received&&(!lastSync||received>lastSync))lastSync=received});if(lastSync){try{localStorage.setItem(K.last,lastSync)}catch{}}if(data.closed){setStatus("This conversation is closed.");input.disabled=true;send.disabled=true;human.disabled=true}else if(data.humanConnected){setStatus("Jonathan has joined the conversation.");human.disabled=true}else if(data.takeoverRequested){setStatus("Jonathan has your message. He’ll reply here when available.");human.disabled=true}else setStatus("")}catch(error){setStatus(error.message||"Connection problem. I’ll retry.")}}
function schedule(){clearInterval(syncTimer);if(open){syncTimer=setInterval(sync,4000);sync()}}
function setOpen(value){open=!!value;if(open&&!launcherVisible)revealLauncher();panel.hidden=!open;root.classList.toggle("jh-cognipal--open",open);launcher.setAttribute("aria-expanded",open?"true":"false");launcher.setAttribute("aria-label",open?"Close CogniPal web chat":"Open CogniPal web chat");if(open){markEngaged();window.setTimeout(()=>input.focus(),50)}else launcher.focus();schedule()}
launcher.addEventListener("click",()=>setOpen(!open));close.addEventListener("click",()=>setOpen(false));document.addEventListener("keydown",event=>{if(event.key==="Escape"&&open)setOpen(false)});
form.addEventListener("submit",async event=>{event.preventDefault();const value=input.value.trim();if(!value||sending)return;markEngaged();input.value="";busy(true);setStatus("Sending…");try{const data=await post("/api/cognipal/message",{...basePayload(),text:value,requestHuman:false});addMessage("inbound",value,new Date().toISOString(),"You",data.messageId||`sent-${Date.now()}`);setStatus("Sent");await sync()}catch(error){setStatus(error.message||"Message could not be sent.")}finally{busy(false);input.focus()}});
input.addEventListener("keydown",event=>{if(event.key==="Enter"&&!event.shiftKey){event.preventDefault();form.requestSubmit()}});
human.addEventListener("click",async()=>{if(sending||humanMode==="human"||humanMode==="takeover_requested")return;markEngaged();busy(true);setStatus("Letting Jonathan know…");try{const message="I’d like to speak to Jonathan.";const data=await post("/api/cognipal/message",{...basePayload(),text:message,requestHuman:true});addMessage("inbound",message,new Date().toISOString(),"You",data.messageId||`human-${Date.now()}`);humanMode="takeover_requested";setStatus("Jonathan has your message. He’ll reply here when available.");human.disabled=true;await sync()}catch(error){setStatus(error.message||"I couldn’t send that request just now.");human.disabled=false}finally{send.disabled=false;input.disabled=false;sending=false}});
document.addEventListener("visibilitychange",()=>{if(!document.hidden&&open)sync()});window.addEventListener("online",()=>{if(open)sync()});
})();
